int n;
const int maxN = 1e6 + 10;
int a[maxN];
ll best[maxN];
ll pref[maxN];
int sec_mn[maxN];
ll pref_sec[maxN];
int MN[maxN];
int f[maxN];
void solve() {
    cin >> n;
    for (int i = 1; i <= n; i++) cin >> a[i];
    for (int i = 0; i <= n - 1; i++) {
        best[i] = 0;
    }
    vector<int> suf_max;
    suf_max.reserve(n);
    for (int i = n; i >= 1; i--) {
        if (suf_max.empty() || a[i] > a[suf_max.back()]) {
            suf_max.emplace_back(i);
        }
    }
    int mn = 1e9;
    sec_mn[0] = 1e9;
    MN[0] = 1e9;
    int ind = -1;
    for (int i = 1; i <= n; i++) {
        sec_mn[i] = sec_mn[i - 1];
        if (a[i] < mn) {
            if (ind != -1) {
                f[ind] = i;
            }
            sec_mn[i] = mn;
            mn = a[i];
            ind = i;
        }
        else if (a[i] < sec_mn[i]) {
            sec_mn[i] = a[i];
        }
        MN[i] = mn;
        pref[i] = pref[i - 1] + mn;
        pref_sec[i] = pref_sec[i - 1] + sec_mn[i];
    }
    assert(ind != -1);
    f[ind] = n + 1;
    best[0] = pref[n];
    vector<int> st{n + 1};
    a[n + 1] = -1e9;
    for (int i = n; i >= 1; i--) {
        if (MN[i - 1] > a[i]) {
            for (int id: suf_max) {
                if (id <= i) break;
                int cur_mn = min(a[i] + a[id], MN[i - 1]);
                int l = 0;
                int r = st.size();
                while (r - l > 1) {
                    int mid = (l + r) / 2;
                    if (a[st[mid]] <= cur_mn) l = mid;
                    else r = mid;
                }
                int upto = min(id - 1, st[l] - 1);
                ll val = pref[i - 1] + cur_mn * 1LL * (upto - i + 1);
//                if (i == 3 && id == 5) {
//                    cout << " HI " << endl;
//                    cout << val << " " << cur_mn << " " << upto << endl;
//                }
                if (upto + 1 < id) {
                    int upup = min(f[i], id);
//                    if (i == 1 && id == 4) {
//                        cout << val << " ???? " << upup << endl;
//                    }
                    assert(upup - 1 >= upto);
                    val += pref_sec[upup - 1] - pref_sec[upto];
                    val += pref[id - 1] - pref[upup - 1];
                }
                best[id - i] = max(best[id - i], val);
                if (a[i] + a[id] >= MN[i - 1]) break;
            }
        }
        while (!st.empty() && a[i] <= a[st.back()]) st.pop_back();
        st.emplace_back(i);
    }
    for (int i = n - 2; i >= 0; i--) best[i] = max(best[i], best[i + 1]);
    for (int i = 0; i < n; i++) cout << best[i] << " ";
    cout << '\n';
}
